<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/audit.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/report_error.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405);$auth=requireAuth();$uid=authTenantId($auth);$actorId=authActorId($auth);$d=json_decode(file_get_contents('php://input'),true)?:[];$year=(int)($d['year']??0);$category=strtoupper(trim((string)($d['category']??'')));$name=trim((string)($d['beneficiary_name']??''));$fiscal=trim((string)($d['beneficiary_fiscal_id']??''));$gross=round((float)($d['gross_amount']??0),3);$withheld=round((float)($d['withheld_amount']??0),3);$paymentId=(int)($d['source_supplier_payment_id']??0);$notes=trim((string)($d['notes']??''));
    if($year<2000||$year>2200||!in_array($category,['SUPPLIER','PAYROLL','OTHER'],true)||$gross<0||$withheld<0||$withheld>$gross)throw new InvalidArgumentException('Invalid employer declaration line');$conn=db();requirePermission($conn,$uid,'reports.view');$conn->begin_transaction();
    if($paymentId>0){if($category!=='SUPPLIER')throw new InvalidArgumentException('A supplier payment can only be linked to a supplier line');$s=$conn->prepare("SELECT COALESCE(sp.amount_tnd,sp.amount*si.exchange_rate) amount,sp.payment_date,s.name,s.fiscal_id FROM erp_supplier_payments sp JOIN erp_supplier_invoices si ON si.id=sp.supplier_invoice_id JOIN suppliers s ON s.id=si.supplier_id AND s.user_id=sp.user_id WHERE sp.id=? AND sp.user_id=? AND sp.voided_at IS NULL FOR UPDATE");$s->bind_param('ii',$paymentId,$uid);$s->execute();$source=$s->get_result()->fetch_assoc();$s->close();if(!$source||substr($source['payment_date'],0,4)!==(string)$year)throw new InvalidArgumentException('Supplier payment is missing or outside the declaration year');$gross=round((float)$source['amount'],3);$name=$source['name'];$fiscal=$source['fiscal_id']??'';}
    if($name==='')throw new InvalidArgumentException('Beneficiary name is required');$s=$conn->prepare("INSERT INTO erp_employer_declarations(user_id,declaration_year,status,created_by) VALUES(?,?,'DRAFT',?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)");$s->bind_param('iii',$uid,$year,$actorId);$s->execute();$declarationId=(int)$s->insert_id;$s->close();$s=$conn->prepare("SELECT status FROM erp_employer_declarations WHERE id=? AND user_id=? FOR UPDATE");$s->bind_param('ii',$declarationId,$uid);$s->execute();$header=$s->get_result()->fetch_assoc();$s->close();if(!$header||$header['status']!=='DRAFT')throw new DomainException('Only draft declarations can be edited');$payment=$paymentId?:null;
    $s=$conn->prepare('INSERT INTO erp_employer_declaration_lines(declaration_id,user_id,category,beneficiary_name,beneficiary_fiscal_id,gross_amount,withheld_amount,source_supplier_payment_id,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->bind_param('iisssddisi',$declarationId,$uid,$category,$name,$fiscal,$gross,$withheld,$payment,$notes,$actorId);$s->execute();$id=(int)$s->insert_id;$s->close();auditLog($conn,$uid,$actorId,'EMPLOYER_DECLARATION.LINE_ADDED','EMPLOYER_DECLARATION_LINE',$id,null,['year'=>$year,'category'=>$category,'beneficiary_name'=>$name,'beneficiary_fiscal_id'=>$fiscal,'gross_amount'=>$gross,'withheld_amount'=>$withheld,'source_supplier_payment_id'=>$payment]);$conn->commit();jsonResponse(['success'=>true,'id'=>$id,'declaration_id'=>$declarationId,'gross_amount'=>$gross]);
}catch(Throwable $e){if(isset($conn))try{$conn->rollback();}catch(Throwable $ignored){}reportFailureResponse($e,'Could not save the employer declaration line.','EMPLOYER_DECLARATION_SAVE_FAILED');}
